using Mbb.Archive.BuildingBlocks.Domain;namespace Mbb.Archive.Modules.AccessControl.Domain.Roles;public sealed class Role:AggregateRoot<Guid>{private readonly List<RolePermission> _permissions=[];private Role(){}private Role(Guid id,string code,string name):base(id){if(string.IsNullOrWhiteSpace(code)||string.IsNullOrWhiteSpace(name))throw new DomainRuleViolationException("Role code and name required.");Code=code.Trim();Name=name.Trim();}public string Code{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public IReadOnlyCollection<RolePermission> Permissions=>_permissions.AsReadOnly();public static Role Create(string code,string name)=>new(Guid.CreateVersion7(),code,name);public void Grant(string permission){if(string.IsNullOrWhiteSpace(permission))throw new DomainRuleViolationException("Permission is required.");var p=permission.Trim().ToLowerInvariant();if(_permissions.Any(x=>x.Permission==p))return;_permissions.Add(new RolePermission(Guid.CreateVersion7(),Id,p));}}
public sealed class RolePermission:Entity<Guid>{private RolePermission(){}internal RolePermission(Guid id,Guid roleId,string permission):base(id){RoleId=roleId;Permission=permission;}public Guid RoleId{get;private set;}public string Permission{get;private set;}=string.Empty;}
public sealed class UserRole:Entity<Guid>{private UserRole(){}private UserRole(Guid id,string subjectId,Guid roleId):base(id){SubjectId=subjectId;RoleId=roleId;}public string SubjectId{get;private set;}=string.Empty;public Guid RoleId{get;private set;}public static UserRole Assign(string subjectId,Guid roleId){if(string.IsNullOrWhiteSpace(subjectId))throw new DomainRuleViolationException("Subject id is required.");return new(Guid.CreateVersion7(),subjectId.Trim(),roleId);}}
